import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Contraste é a diferença entre as partes mais escuras e mais claras de uma foto. É o que faz uma imagem parecer marcante e sólida, ou chapada e cinza.</p>\n<p>Uma foto com bom contraste tem sombras profundas, realces claros e uma sensação clara de profundidade. Uma foto com pouco contraste parece com neblina, como se tivesse sido tirada através de um nevoeiro.</p>\n<p>Este guia explica como o contraste funciona, como usar bem o controle e as predefinições, e como dar impacto sem cortar os realces nem esmagar as sombras. Você vai ver retratos, paisagens, capturas de tela e os erros que estragam uma boa imagem.</p>\n<p>Para dar esse impacto na sua foto, o <a href=\"/pt/ajustar-contraste-da-imagem/\">Editor de contraste de imagem</a> mostra o antes e o depois ao vivo enquanto você ajusta o controle.</p>\n<h2 id=\"what-contrast-does\">O que o contraste realmente faz</h2>\n<p>O contraste estica ou aperta a faixa tonal de uma imagem. Ao aumentar, os pixels escuros ficam mais escuros e os claros mais claros, ampliando a distância entre eles.</p>\n<p>Diminuir o contraste faz o contrário. Ele aproxima escuros e claros, suavizando a imagem e reduzindo a diferença entre as partes mais claras e mais escuras.</p>\n<p>O contraste não muda muito o brilho geral. Uma foto de alto contraste pode ser escura ou clara no geral, mas suas sombras e seus realces estarão bem distantes de qualquer jeito.</p>\n<p>Pense no contraste como a distância entre o preto mais escuro e o branco mais claro da foto. Quanto maior essa distância, mais marcante a imagem parece; quanto menor, mais chapada ela fica.</p>\n<h2 id=\"why-photos-look-flat\">Por que as fotos parecem chapadas</h2>\n<p>A neblina é a causa mais comum de uma foto chapada. Nevoeiro, névoa e ar úmido espalham a luz, o que levanta as sombras e apaga os realces até a imagem inteira ficar no meio.</p>\n<p>A luz nublada também achata as fotos. Um céu encoberto dá uma luz suave e uniforme, sem sombras fortes, então a imagem já nasce com pouca faixa tonal.</p>\n<p>Fotos antigas digitalizadas também costumam parecer chapadas. O tempo desbota as impressões, o scanner lê os tons errado, e o resultado é uma imagem cinza e turva, sem pretos profundos nem brancos claros.</p>\n<p>A câmera do celular pode produzir fotos chapadas com pouca luz. O sensor tem dificuldade de capturar a faixa completa, e a imagem sai comprimida nos tons médios.</p>\n<h2 id=\"slider-explained\">O controle de contraste, explicado</h2>\n<p>O controle de contraste vai de valores negativos a positivos, com zero significando nenhuma mudança. Mover para a direita aumenta o contraste, e mover para a esquerda diminui.</p>\n<p>Movimentos pequenos fazem uma grande diferença. Uma mudança de 10 a 20 por cento costuma bastar para corrigir uma foto chapada, e movimentos maiores cortam os realces e esmagam as sombras rapidinho.</p>\n<p>A ferramenta mostra sua foto em mais 20 por cento logo depois do envio. Esse ponto de partida já dá uma ideia imediata de como fica um reforço moderado de contraste.</p>\n<p>Arraste o controle devagar e observe a prévia. A atualização ao vivo mostra exatamente como a imagem reage, então você pode parar no ponto em que a foto fica certa.</p>\n<h2 id=\"quick-presets\">Predefinições rápidas para correções em um clique</h2>\n<p>A ferramenta inclui predefinições rápidas que aplicam valores comuns de contraste num só clique. São um jeito rápido de testar níveis diferentes sem arrastar o controle.</p>\n<p>Predefinições são um ponto de partida, não a resposta final. Clique numa, olhe a prévia e depois ajuste com o controle se o resultado estiver perto, mas não exato.</p>\n<p>Use as predefinições para comparar opções rapidinho. Uma predefinição em mais 10 por cento ao lado de uma em mais 30 por cento mostra quanto contraste a foto aguenta antes de cortar.</p>\n<p>Para um lote de fotos parecidas, a mesma predefinição mantém os resultados consistentes. Um conjunto de paisagens com neblina, todas com o mesmo reforço, parece uma série.</p>\n<h2 id=\"compare-modes\">Modos de comparação: antes, depois e dividido</h2>\n<p>Os modos de comparação mostram a original e a versão editada juntas. O modo Depois mostra a imagem com mais contraste, o modo Antes mostra a original, e o modo Dividido mostra as duas lado a lado.</p>\n<p>A comparação dividida é a mais útil para o trabalho de contraste. Ela permite ver exatamente quais sombras aprofundaram e quais realces clarearam, com uma linha clara entre as duas versões.</p>\n<p>A comparação em tela cheia mostra a foto maior. É o melhor jeito de avaliar uma edição de contraste, porque a imagem em tamanho real mostra cortes que uma prévia pequena esconde.</p>\n<p>Confira a comparação antes de cada download. Uma olhada rápida pega realces cortados e sombras esmagadas que uma prévia pequena poderia esconder.</p>\n<h2 id=\"contrast-and-colour\">Contraste e cor: como eles se afetam</h2>\n<p>O contraste afeta a cor além do tom. Aumentar o contraste deixa as cores mais ricas e saturadas, porque os escuros ficam mais escuros e os claros mais claros ao redor delas.</p>\n<p>Diminuir o contraste apaga as cores. Uma imagem suave, de baixo contraste, tem tons gentis e pastéis, o que combina com retratos e paisagens de sonho.</p>\n<p>Essa ligação significa que uma mudança de contraste também é uma mudança de cor. Uma foto que precisa de mais impacto pode precisar de contraste, enquanto uma foto que precisa de mais cor pode precisar de saturação.</p>\n<p>Para o trabalho de cor em si, use o <a href=\"/pt/ajustar-saturacao-da-imagem/\">ajustar a saturação da foto</a> depois de definir o contraste. Os dois controles juntos dão controle total sobre o visual da imagem.</p>\n<h2 id=\"contrast-for-portraits\">Contraste para retratos</h2>\n<p>Retratos precisam de contraste leve. Um rosto com contraste demais parece duro e envelhecido, com sombras profundas sob os olhos e manchas claras na testa.</p>\n<p>Comece com um pequeno reforço de 10 por cento e confira a pele. O rosto deve parecer definido, não como se as sombras tivessem sido pintadas.</p>\n<p>O contraste negativo pode ajudar um retrato duro. O sol do meio-dia cria sombras fortes no rosto, e uma pequena redução suaviza elas sem perder a forma geral.</p>\n<p>Para um retrato tirado com luz suave de janela, o contraste muitas vezes já está certo. Um pequeno reforço de 5 a 10 por cento basta, e movimentos maiores fazem mais mal que bem.</p>\n<h2 id=\"contrast-for-landscapes\">Contraste para paisagens</h2>\n<p>Paisagens ganham mais com o contraste. Uma cena de montanha com neblina, um vale com nevoeiro ou um céu sem graça ganham profundidade e drama com um reforço moderado.</p>\n<p>Use um reforço de 15 a 25 por cento para uma paisagem com neblina. As sombras aprofundam, os realces clareiam, e a cena ganha o impacto que a neblina tirou.</p>\n<p>Observe o céu enquanto aumenta o contraste. As nuvens cortam primeiro, virando brancos vazios sem forma, e um céu cortado estraga uma paisagem que seria boa.</p>\n<p>Para uma paisagem com céu claro e primeiro plano escuro, aceite um meio-termo. O contraste estica as duas pontas, então o céu e o chão se movem em direções opostas.</p>\n<h2 id=\"contrast-for-screenshots\">Contraste para capturas de tela e documentos</h2>\n<p>Capturas de tela e documentos digitalizados precisam de contraste para legibilidade. O texto precisa se destacar do fundo, e uma digitalização de baixo contraste com texto cinza é difícil de ler.</p>\n<p>Cole uma captura de tela direto com Ctrl+V para pular a etapa de salvar. A imagem aparece no editor na hora, pronta para ajustar.</p>\n<p>Aumente o contraste até o texto ficar escuro e o fundo branco. Um documento com texto preto forte sobre um fundo branco limpo é fácil de ler e de imprimir.</p>\n<p>Cuidado com o ruído no fundo. Uma digitalização com muito contraste pode mostrar manchas e artefatos, principalmente num JPEG que já estava comprimido.</p>\n<h2 id=\"negative-contrast\">Contraste negativo: como suavizar fotos duras</h2>\n<p>O contraste negativo suaviza uma imagem ao aproximar escuros e claros. É a escolha certa para uma foto tirada sob o sol forte do meio-dia.</p>\n<p>Use valores como menos 10 ou menos 20 por cento para suavizar sombras fortes num retrato. O rosto mantém sua forma, mas as bordas duras se dissolvem num visual mais gentil.</p>\n<p>O contraste negativo também combina com paisagens suaves e de sonho. Uma cena de manhã com névoa e baixo contraste parece calma e silenciosa, o que combina com o clima da foto.</p>\n<p>Não exagere. Uma foto com pouco contraste demais parece cinza e sem vida, como se tivesse sido tirada através de nevoeiro, mesmo num dia limpo.</p>\n<h2 id=\"clipping-and-crushing\">Como cortar realces e esmagar sombras</h2>\n<p>O corte acontece quando os realces são empurrados além do branco puro. O detalhe de uma nuvem clara ou de uma camisa branca some, e a área vira um vazio sem forma.</p>\n<p>O esmagamento acontece quando as sombras são empurradas além do preto puro. O detalhe de um casaco escuro ou de um canto com sombra some, e a área vira uma mancha preta sólida.</p>\n<p>Os dois são permanentes no arquivo exportado. Depois que o detalhe é cortado ou esmagado, nenhuma edição posterior traz ele de volta, então confira os extremos antes de baixar.</p>\n<p>Use a comparação para identificar corte e esmagamento. A comparação dividida mostra exatamente quais áreas perderam detalhe, e uma pequena redução no controle geralmente restaura elas.</p>\n<h2 id=\"formats-and-export\">Formatos e exportação</h2>\n<p>A ferramenta aceita formatos comuns de imagem, incluindo JPG, PNG, WebP e HEIC, com arquivos de até 20 MB. Você pode exportar em JPG, PNG ou WebP conforme a necessidade.</p>\n<p>Exportar em PNG ou WebP preserva a transparência da imagem base. Se a sua fonte for um gráfico PNG transparente, a exportação com contraste editado mantém as áreas vazadas intactas.</p>\n<p>Para fotos, JPG com qualidade alta funciona bem. O contraste não aumenta muito o tamanho do arquivo, então a exportação fica perto do peso original.</p>\n<p>O controle de qualidade aparece para exportações em JPG e WebP e some para PNG, porque o PNG não tem perda de qualidade e não tem ajuste de qualidade.</p>\n<h2 id=\"contrast-vs-brightness\">Contraste ou brilho: qual vem primeiro?</h2>\n<p>O brilho define o nível geral, e o contraste define a amplitude ao redor desse nível. Uma foto escura demais precisa de brilho primeiro, porque o contraste não corrige o nível.</p>\n<p>Uma foto chapada, mas com a luz certa, precisa só de contraste. Clareá-la deixaria ela mais clara e mais chapada, não melhor, então pule a etapa de brilho.</p>\n<p>Quando uma foto precisa dos dois, faça o brilho primeiro e depois o contraste. A ordem importa, porque o brilho muda o que o ajuste de contraste precisa fazer.</p>\n<p>Para a comparação completa, leia <a href=\"/pt/blog/brilho-vs-exposicao-vs-contraste/\">Brilho, exposição e contraste: qual a diferença?</a>.</p>\n<h2 id=\"privacy-local-processing\">Privacidade: editar sem enviar nada</h2>\n<p>Toda a edição de contraste acontece no seu navegador. Suas fotos nunca são enviadas para um servidor, o que importa quando as imagens são pessoais, fotos de família ou trabalho de cliente.</p>\n<p>Isso é uma vantagem real sobre editores na nuvem. Uma foto de família ou um documento particular não deveria viajar para um servidor que você não conhece, só para adicionar contraste.</p>\n<p>A ferramenta também remove os dados de GPS do EXIF na exportação. Uma foto com contraste editado, baixada da ferramenta, não carrega nenhum registro de onde foi tirada.</p>\n<p>Guarde a foto original sem edições. Depois que uma mudança de contraste é aplicada numa exportação, não dá para desfazê-la a partir daquele arquivo, então a original é a sua única cópia limpa.</p>\n<h2 id=\"common-mistakes\">Erros comuns ao ajustar o contraste</h2>\n<p>O erro mais comum é adicionar contraste demais. Uma foto levada a mais 50 por cento ou mais perde os realces e as sombras por completo, e o resultado é uma imagem dura, parecida com um cartaz.</p>\n<p>Outro erro é usar o contraste para corrigir uma foto escura. Uma foto escura com alto contraste continua escura, só com sombras mais profundas, e o assunto continua escondido.</p>\n<p>Muita gente também esquece de conferir os extremos. Um céu ou uma sombra que parece bom numa prévia pequena pode estar cortado ou esmagado em tamanho real, então confira sempre o resultado grande.</p>\n<p>Por fim, não ajuste o mesmo JPG várias vezes. Cada salvamento adiciona dano, então volte sempre ao arquivo original quando quiser outro nível de contraste.</p>\n<h2 id=\"contrast-workflow\">Um fluxo de trabalho para edições limpas de contraste</h2>\n<p>Comece com o arquivo original e decida se a foto está chapada, dura ou com a amplitude certa. Uma foto chapada precisa de reforço, uma dura precisa de redução, e uma certa não precisa de nada.</p>\n<p>Aplique o contraste e depois confira a comparação. A comparação dividida mostra exatamente quais sombras aprofundaram e quais realces clarearam.</p>\n<p>Confira os realces e as sombras separadamente. Os realces cortam primeiro com um reforço, e as sombras esmagam primeiro com o mesmo movimento, então os dois extremos precisam de atenção.</p>\n<p>Exporte com qualidade alta e confira o resultado em tamanho real. Dê zoom nas áreas claras e escuras e confirme que nenhum detalhe foi perdido.</p>\n<h2 id=\"contrast-for-black-white\">Contraste para fotos em preto e branco</h2>\n<p>Fotos em preto e branco vivem ou morrem pelo contraste. Sem cor para carregar a imagem, a faixa tonal é tudo, e uma foto preto e branco chapada parece cinza e sem vida.</p>\n<p>Use um reforço de contraste mais forte para preto e branco que para cor. Um reforço de 20 a 30 por cento dá à imagem os pretos profundos e os brancos claros que deixam ela marcante.</p>\n<p>Observe os tons médios enquanto aumenta o contraste. Um retrato em preto e branco precisa de tons de cinza suaves na pele, e contraste demais transforma o rosto em manchas duras de preto e branco.</p>\n<p>Para uma paisagem em preto e branco, o contraste é sua ferramenta principal. As montanhas, o céu e o primeiro plano ganham definição com uma amplitude tonal clara.</p>\n<p>Para o passo a passo, veja <a href=\"/pt/blog/como-ajustar-contraste-da-foto/\">Como ajustar o contraste da foto</a>. Para a comparação, leia <a href=\"/pt/blog/brilho-vs-exposicao-vs-contraste/\">Brilho, exposição e contraste: qual a diferença?</a>, e para corrigir uma foto escura antes de adicionar contraste, experimente o <a href=\"/pt/ajustar-brilho-da-imagem/\">ajustar o brilho da foto</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Quanto contraste devo adicionar a uma foto chapada?","answer":"Comece com 10 a 20 por cento e confira a prévia. A maioria das fotos chapadas precisa só de um pequeno reforço, e movimentos maiores cortam os realces e esmagam as sombras rapidinho. Aumente em passos pequenos e pare quando a imagem parecer sólida sem perder detalhe."},{"question":"Por que minha foto ficou dura depois de adicionar contraste?","answer":"O contraste foi levado longe demais, o que aprofunda as sombras e clareia os realces além do ponto em que o detalhe sobrevive. Reduza o controle até a pele, o céu e as áreas de sombra mostrarem textura de novo. Um reforço de 10 por cento costuma bastar."},{"question":"O contraste resolve uma foto escura demais?","answer":"Não. O contraste muda a amplitude, não o nível, então uma foto escura com alto contraste continua escura, só com sombras mais profundas. Clareie a foto primeiro com o editor de brilho e depois adicione contraste se ela parecer chapada."},{"question":"Devo usar contraste positivo ou negativo para um retrato?","answer":"Geralmente um pequeno reforço positivo, de 5 a 10 por cento, que define o rosto sem dureza. Para um retrato tirado sob o sol forte do meio-dia, o contraste negativo de menos 10 a menos 20 por cento suaviza as sombras fortes e favorece a pele."},{"question":"Aumentar o contraste também deixa as cores mais fortes?","answer":"Sim. Aumentar o contraste deixa as cores mais ricas, porque os escuros ficam mais escuros e os claros mais claros ao redor delas. Se as cores ficarem fortes demais, reduza um pouco a saturação depois com o editor de saturação."},{"question":"É seguro editar o contraste de uma foto pessoal numa ferramenta de navegador?","answer":"Sim, porque todo o processamento acontece localmente no seu navegador e nada é enviado para um servidor. A ferramenta também remove os dados de GPS do EXIF na exportação. Guarde o arquivo original se quiser testar outro nível de contraste depois."}];
